import React, {
  createContext,
  useContext,
  useState,
  useCallback,
  ReactNode,
} from "react"

export type ToastType = "success" | "error" | "info" | "warning"

interface Toast {
  id: number
  message: string
  type: ToastType
}

interface ToastContextValue {
  showToast: (message: string, type?: ToastType) => void
}

const ToastContext = createContext<ToastContextValue | null>(null)

let nextId = 0

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([])

  const showToast = useCallback((message: string, type: ToastType = "info") => {
    const id = ++nextId
    setToasts(prev => [...prev, { id, message, type }])
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id))
    }, 4000)
  }, [])

  const typeStyles: Record<ToastType, string> = {
    success: "bg-green-600",
    error: "bg-red-600",
    info: "bg-blue-600",
    warning: "bg-yellow-500",
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {/* Portal-style fixed container */}
      <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 items-end sm:items-end max-sm:right-0 max-sm:left-0 max-sm:items-center max-sm:px-4">
        {toasts.map(toast => (
          <div
            key={toast.id}
            className={`${typeStyles[toast.type]} text-white text-sm px-4 py-3 rounded-lg shadow-lg animate-fade-in max-w-sm w-full sm:w-auto`}
          >
            {toast.message}
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  )
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error("useToast must be used inside ToastProvider")
  return ctx
}
