// Firebase must only initialize in the browser — GATSBY_* env vars are
// undefined during SSR, which causes auth/invalid-api-key at build time.
import { initializeApp, getApps, FirebaseApp } from "firebase/app"
import { getAuth, Auth } from "firebase/auth"
import { getFirestore, Firestore } from "firebase/firestore"

// Colecciones planeadas (referencia):
// clients/{clientId}           — info personal + vehículos + portalTokens
// appointments/{appointmentId} — citas vinculadas a cliente
// serviceTickets/{ticketId}    — fichas de servicio con impuestos calculados
// appointmentRequests/{id}     — solicitudes de cita desde el portal (Phase 07)
// settings/services            — lista de servicios regulares
// settings/taxes               — GST (5%) y QST (9.975%) Quebec

let auth: Auth | undefined
let db: Firestore | undefined

if (typeof window !== "undefined") {
  const firebaseConfig = {
    apiKey: process.env.GATSBY_FIREBASE_API_KEY,
    authDomain: process.env.GATSBY_FIREBASE_AUTH_DOMAIN,
    projectId: process.env.GATSBY_FIREBASE_PROJECT_ID,
    storageBucket: process.env.GATSBY_FIREBASE_STORAGE_BUCKET,
    messagingSenderId: process.env.GATSBY_FIREBASE_MESSAGING_SENDER_ID,
    appId: process.env.GATSBY_FIREBASE_APP_ID,
  }

  const app: FirebaseApp =
    getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0]
  auth = getAuth(app)
  db = getFirestore(app)
}

export { auth, db }
